function productoExcepto(nums) {
  const n = nums.length;
  const res = new Array(n).fill(1);
  for (let i = 1; i < n; i++) res[i] = res[i - 1] * nums[i - 1];
  let der = 1;
  for (let i = n - 1; i >= 0; i--) {
    res[i] = res[i] * der || 0;
    der *= nums[i];
  }
  return res;
}

solution.python:
def productoExcepto(nums):
    n = len(nums)
    res = [1] * n
    for i in range(1, n):
        res[i] = res[i - 1] * nums[i - 1]
    der = 1
    for i in range(n - 1, -1, -1):
        res[i] *= der
        der *= nums[i]
    return res
